# Wedge distribution ----

#' Wedge distribution
#'
#' The wedge distribution has a support of 0 to 1 and has a linear probability
#' density function over that support.
#'
#' The `rwedge` can be combined with quantile functions to
#' skew standard distributions, or introduce correlation or down weight
#' certain parts of the distribution.
#'
#' @param n number of observations
#' @param x vector of quantiles
#' @param q vector of quantiles
#' @param p vector of probabilities
#' @param log logical; if TRUE, probabilities p are given as log(p).
#' @param log.p logical; if TRUE, probabilities p are given as log(p).
#' @param lower.tail logical; if TRUE (default), probabilities are `P[X<=x]`
#'   otherwise `P[X>x]`.
#' @param a a gradient from -2 (left skewed) to 2 (right skewed)
#' @return a vector of probabilities, quantiles, densities or samples.
#' @name wedge
#' @concept distributions
#' @examples
#'
#' pwedge(seq(0, 1, 0.1), a = 1)
#' dwedge(seq(0, 1, 0.1), a = 1)
#' qwedge(c(0.25, 0.5, 0.75), a = -1)
#'
#' stats::cor(
#'   stats::qnorm(rwedge(1000, a = 2)),
#'   stats::qnorm(rwedge(1000, a = -2))
#' )
NULL


#' @inherit wedge
#' @concept distributions
#' @export
pwedge = function(q, a, log.p = FALSE) {
  a = rep(a, length.out = length(q))
  b = (1 - a / 2)
  y = dplyr::case_when(
    a > 2 | a < -2 ~ NaN,
    q < 0 | q > 1 ~ NaN,
    TRUE ~ a * q + b
  )
  if (log.p) {
    return(log(y))
  }
  return(y)
}

#' @inherit wedge
#' @concept distributions
#' @export
dwedge = function(x, a, lower.tail = TRUE, log = FALSE) {
  a = rep(a, length.out = length(x))
  b = (1 - a / 2)
  y = dplyr::case_when(
    a > 2 | a < -2 ~ NaN,
    x < 0 | x > 1 ~ NaN,
    TRUE ~ a / 2 * x^2 + b * x
  )
  if (!lower.tail) {
    y = 1 - y
  }
  if (log) {
    return(log(y))
  }
  return(y)
}

#' @inherit wedge
#' @concept distributions
#' @export
qwedge = function(p, a, lower.tail = TRUE, log.p = FALSE) {
  a = rep(a, length.out = length(p))
  b = (1 - a / 2)
  if (log.p) {
    p = exp(p)
  }
  if (!lower.tail) {
    p = 1 - p
  }
  x = dplyr::case_when(
    a > 2 | a < -2 ~ NaN,
    p < 0 | p > 1 ~ NaN,
    TRUE ~
      ifelse(
        a > 0,
        -(b / a) + sqrt(2 * p / a + (b^2) / (a^2)),
        -(b / a) - sqrt(2 * p / a + (b^2) / (a^2))
      )
  )
  return(x)
}

#' @inherit wedge
#' @concept distributions
#' @export
rwedge = function(n, a) {
  return(qwedge(stats::runif(n), a))
}


## Bernoulli / Categorical ----

#' A random Bernoulli sample as a logical value
#'
#' @inheritParams reparam-dist
#' @return a vector of logical values of size `n`
#'
#' @export
#' @concept distributions
#'
#' @examples
#' table(rbern(100, 0.25))
rbern = function(n, prob) {
  as.logical(stats::runif(n) < prob)
}

#' Sampling from the multinomial equivalent of the Bernoulli distribution
#'
#' @param n a sample size
#' @param prob a (optionally named) vector of probabilities that will be
#'   normalised to sum to 1
#' @param factor if not FALSE then factor levels will either be taken from the
#'   names of `prob` first, or if this is a character vector from this.
#' @return a vector of random class labels of length `n`. Labels come from names
#'   of `prob` or from a character vector in `factor`.
#'
#' @export
#' @concept distributions
#' @examples
#'
#' prob = c("one" = 0.1, "two" = 0.2, "seven" = 0.7)
#' table(rcategorical(1000, prob))
#' rcategorical(10, prob, factor = TRUE)
#' rcategorical(10, rep(1, 26), factor = letters)
#'
rcategorical = function(n, prob, factor = FALSE) {
  if (length(n) > 0) {
    prob = prob / sum(prob)
    to_test = cumsum(prob)
    against = stats::runif(
      if (is.numeric(n) && length(n) == 1) n else length(n)
    )
    tmp = matrix(
      sapply(to_test, FUN = function(x) x <= against),
      nrow = length(against)
    )
    which = apply(tmp, MARGIN = 1, sum) + 1
  } else {
    which = numeric()
  }
  if (isFALSE(factor)) {
    if (is.null(names(prob))) {
      return(which)
    } else {
      return(names(prob)[which])
    }
  } else {
    if (is.null(names(prob))) {
      if (is.character(factor)) {
        if (length(factor) != length(prob)) {
          stop(
            "If levels are given in `factor`, it must be the same length as `prob`."
          )
        }
        return(factor(factor[which], levels = factor))
      } else {
        stop(
          "if a factor is wanted then either `prob` must be named or the levels must be provided as a character vector in `factor`"
        )
      }
    } else {
      if (is.character(factor)) {
        warning(
          "Factor levels are supplied in both names of `prob` and `factor` - defaulting to names of `prob`"
        )
      }
      return(factor(names(prob)[which], levels = names(prob)))
    }
  }
}


#' Randomly sample incident times in an exponentially growing process
#'
#' @param n the number of items to sample
#' @param r and exponential growth rate (per unit time)
#' @param t_end the end of the observation period
#' @param t_start the start of the observation period
#'
#' @returns a vector of `n` samples from an exponential growth process
#' @export
#' @concept distributions
#'
#' @examples
#' graphics::hist(rexpgrowth(1000, 0.1, 40), breaks = 40)
#' graphics::hist(rexpgrowth(1000, -0.1, 40), breaks = 40)
rexpgrowth = function(n, r, t_end, t_start = 0) {
  # Primary case infection time
  # exponentially distributed in time. Need to make sure we have enough samples
  # before t0 observation cutoff to account for early observed cases.
  if (r == 0) {
    return(stats::runif(n, t_start, t_end))
  }
  trunc_p = stats::pexp(t_end - t_start, abs(r))
  u = stats::runif(n) * trunc_p
  if (r > 0) {
    # growth
    # flipped in time and truncated at start
    return(t_end - stats::qexp(u, r))
  } else {
    # decay
    # truncated at end
    return(stats::qexp(u, -r))
  }
}

#' Randomly sample incident times in an exponentially growing process with initial case load
#'
#' @param I0 the expected number of cases observed in the first day
#' @param r an exponential growth rate (per unit time)
#' @param t_end the end of the observation period
#' @param t_start the start of the observation period
#'
#' @returns a vector of `n` samples from an exponential growth process
#' @export
#' @concept distributions
#'
#' @examples
#' graphics::hist(rexpgrowthI0(10, 0.1, 20), breaks = 40)
#' graphics::hist(rexpgrowthI0(1000, -0.1, 40), breaks = 40)
rexpgrowthI0 = function(I0, r, t_end, t_start = 0) {
  if (r == 0) {
    n = I0 * (t_end - t_start)
    return(rexpgrowth(n, r, t_end, t_start))
  }
  trunc_p = stats::pexp(t_end - t_start, abs(r))
  if (r > 0) {
    day1_p = (trunc_p - stats::pexp(t_end - t_start - 1, r)) / trunc_p
  } else {
    day1_p = stats::pexp(1, -r) / trunc_p
  }
  n = I0 / day1_p
  return(rexpgrowth(n, r, t_end, t_start))
}

## Re parametrisations roxygen ----

#' Re-parametrised distributions
#'
#' @param n number of observations
#' @param x vector of quantiles
#' @param q vector of quantiles
#' @param p vector of probabilities
#' @param dist the distribution name e.g.`lnorm`
#' @param log logical; if TRUE, probabilities p are given as log(p).
#' @param log.p logical; if TRUE, probabilities p are given as log(p).
#' @param lower.tail logical; if TRUE (default), probabilities are `P[X<=x]`
#'   otherwise `P[X>x]`.
#' @param prob the mean probability (vectorised)
#' @param prob.0.5 the median probability (vectorised)
#' @param kappa a coefficient of variation (sd/mean). where 0 is no variability.
#' @param mean the mean value on the true scale (vectorised)
#' @param median the median value on the true scale (vectorised)
#' @param sd the standard deviation on the true scale (vectorised)
#' @param ... passed onto named functions
#'
#' @keywords internal
#' @concept distributions
#'
#' @name reparam-dist
NULL


#' Get a converter that maps an unusual parametrisation to a canonical one.
#'
#' @param dist_name the distribution family as a string, e.g. `lnorm4`
#'
#' @returns a function that takes 2 parameters of the original distrbition and
#' returns a list with the parameters and name of the canonical distribution.
#' @export
#' @concept distributions
#'
#' @examples
#' tmp_fn = reparam_fn("lnorm2")
#' tmp_fn(mean = 1, sd = 2)
reparam_fn = function(dist_name) {
  mapper_name = sprintf(".reparam.%s", dist_name)
  found = exists(mapper_name, envir = asNamespace("pitw"), mode = "function")
  if (!found) stop("reparametrisation not supported: ", dist_name)
  tmp = get(mapper_name, envir = asNamespace("pitw"), mode = "function")
  return(tmp)
}

.reparam.logitnorm2 = function(prob.0.5, kappa, ...) {
  if (any(prob.0.5 < 0 | prob.0.5 > 1, na.rm = TRUE)) {
    stop("prob.0.5 must be greater than zero and smaller than 1")
  }
  if (any(kappa < 0 | kappa > 1, na.rm = TRUE)) {
    stop("kappa must be greater than zero and smaller than 1")
  }
  mu = .logit(prob.0.5)
  sigma = -log(1 - kappa) # maps 0-1 to 0-Inf
  return(list(
    dist = "logitnorm",
    meanlogit = mu,
    sdlogit = sigma
  ))
}

.reparam.beta2 = function(p, kappa, ...) {
  if (any(p < 0 | p > 1, na.rm = TRUE)) {
    stop("p is a probability and must be between 0 and 1")
  }
  if (any(kappa < 0 | kappa > 1, na.rm = TRUE)) {
    stop("kappa must be between 0 (no variability) to 1 (max variability)")
  }

  if (length(kappa) != length(p) & length(kappa) != 1) {
    stop("kappa must be compatible length with p.")
  }
  kappa = rep(kappa, length.out = length(p))

  # for beta distribution to be unimodal 3 conditions have to be true
  # alpha > 1 and beta > 1 and alpha+beta>2
  # this puts constraints on kappa.
  kmax1 = sqrt((1 - p) / (1 + p))
  kmax2 = sqrt(1 / (2 * p - p^2) - 1)
  kmax3 = sqrt((1 - p) / (3 * p))
  kmax = pmin(kmax1, kmax2, kmax3)

  # kappa is actually 0 to 1 where 1 is the most dispersed it is possible to be
  # with a mean of p (and still be unimodal)
  kappa2 = kmax * kappa

  return(list(
    dist = "beta",
    shape1 = ((1 - p) / (kappa2^2 * p) - 1) * p,
    shape2 = ((1 - p) / (kappa2^2 * p) - 1) * (1 - p)
  ))
}

.reparam.norm4 = function(median, kappa, ...) {
  if (any(kappa < 0, na.rm = TRUE)) {
    stop("kappas must be greater than zero")
  }
  return(list(
    dist = "norm",
    mean = median,
    sd = median * kappa
  ))
}

.reparam.lnorm2 = function(mean, sd, ...) {
  if (any(mean < 0, na.rm = TRUE)) {
    stop("means must be greater than zero")
  }
  if (any(sd < 0, na.rm = TRUE)) {
    stop("sds must be greater than zero")
  }
  var = sd^2
  return(list(
    dist = "lnorm",
    meanlog = log(mean / sqrt(var / (mean^2) + 1)),
    sdlog = sqrt(log(var / (mean^2) + 1))
  ))
}

.reparam.lnorm4 = function(median, kappa, ...) {
  if (any(median < 0, na.rm = TRUE)) {
    stop("medians must be greater than zero")
  }
  if (any(kappa < 0, na.rm = TRUE)) {
    stop("coefficient of variation must be greater than zero")
  }
  return(list(
    dist = "lnorm",
    meanlog = log(median),
    sdlog = sqrt(log(kappa^2 + 1))
  ))
}

.reparam.gamma2 = function(mean, sd, ...) {
  if (any(mean < 0, na.rm = TRUE)) {
    stop("means must be greater than zero")
  }
  if (any(sd < 0, na.rm = TRUE)) {
    stop("sds must be greater than zero")
  }
  var = sd^2
  return(list(
    dist = "gamma",
    shape = mean^2 / var, # if shape < 1 then is concave
    rate = mean / var
  ))
}


.reparam.gamma4 = function(median, kappa, ...) {
  if (any(median < 0, na.rm = TRUE)) {
    stop("medians must be greater than zero")
  }
  if (any(kappa < 0, na.rm = TRUE)) {
    stop("kappa (coef of variation) must be greater than zero")
  }

  # Calculate shape directly from the coefficient of variation
  shape = 1 / kappa^2

  # Calculate the exact mean analytically without any numerical optimization
  true_mean = median * (shape / stats::qgamma(0.5, shape = shape, rate = 1))

  return(list(
    dist = "gamma",
    shape = shape,
    rate = 1 / (true_mean * kappa^2)
  ))
}

.reparam.cgamma = function(median, kappa, ...) {
  if (any(median < 0, na.rm = TRUE)) {
    stop("medians must be greater than zero")
  }
  if (any(kappa < 0 | kappa > 1, na.rm = TRUE)) {
    stop("kappa (coef of variation) must be between zero and one")
  }

  # Calculate shape directly from the coefficient of variation
  shape = 1 / kappa^2

  # Calculate the exact mean analytically without any numerical optimization
  true_mean = median * (shape / stats::qgamma(0.5, shape = shape, rate = 1))

  return(list(
    dist = "gamma",
    shape = shape,
    rate = 1 / (true_mean * kappa^2)
  ))
}

.reparam.nbinom2 = function(mean, sd, ...) {
  if (any(mean < 0, na.rm = TRUE)) {
    stop("means must be greater than zero")
  }
  if (any(sd < 0, na.rm = TRUE)) {
    stop("sds must be greater than zero")
  }
  if (any(sd < sqrt(mean), na.rm = TRUE)) {
    stop("sds must be greater than the sqrt of the mean")
  }
  var = sd^2
  return(list(
    dist = "nbinom",
    size = mean^2 / (var - mean),
    prob = mean / var
  ))
}

#' @unit
#' .test_dist("logitnorm", 0, 0.1)
#' .test_dist("logitnorm2", 0.75, 0.2)
#' .test_dist("beta2", 0.75, 0.2)
#' .test_dist("norm4", 1, 0.1)
#' .test_dist("lnorm2", 2, 0.1)
#' .test_dist("lnorm4", 2, 0.1) # has to be narrow for tolerance to work
#' .test_dist("gamma2", 2, 0.1)
#' .test_dist("gamma4", 2, 0.1)
#' .test_dist("cgamma", 2, 0.1)
.test_dist = function(dist, ...) {
  rfn = rlang::as_function(sprintf("r%s", dist))
  pfn = rlang::as_function(sprintf("p%s", dist))
  qfn = rlang::as_function(sprintf("q%s", dist))
  dfn = rlang::as_function(sprintf("d%s", dist))

  ps = seq(0, 1, 0.1)
  qs = qfn(p = ps, ...)
  test_ps = pfn(q = qs, ...)

  testthat::expect_equal(ps, test_ps, info = dist)

  rs = rfn(100000, ...)
  fn = function(x) x * dfn(x, ...)

  mean_analytic = stats::integrate(fn, min(qs, na.rm = TRUE), max(qs, na.rm = TRUE))
  mean_analytic = mean_analytic$value
  mean_sample = mean(rs)

  testthat::expect_equal(
    mean_analytic,
    mean_sample,
    tolerance = 0.01,
    info = dist
  )

  testthat::expect_equal(
    stats::median(rs),
    qdist(dist, 0.5, ...),
    tolerance = 0.1,
    info = dist
  )
}

#' Random sample from a named distribution
#'
#' @inheritParams reparam-dist
#'
#' @export
#' @concept distributions
rdist = function(dist, n, ...) {
  reparam_fn = try(rlang::as_function(sprintf(".reparam.%s", dist)), silent = TRUE)
  if (inherits(reparam_fn, "try-error")) {
    dist_fn = try(rlang::as_function(sprintf("r%s", dist)), silent = TRUE)
    if (inherits(dist_fn, "try-error")) {
      stop(
        "can't resolve function: ",
        sprintf("r%s", dist),
        " or reparameterise it."
      )
    }
    return(dist_fn(n, ...))
  } else {
    param = utils::head(rlang::list2(...), 2)
    dots = utils::tail(rlang::list2(...), -2)
    tmp = rlang::exec(reparam_fn, !!!param)
    dist_fn = try(rlang::as_function(sprintf("r%s", tmp$dist)), silent = TRUE)
    args = c(list(n = n), tmp[2:3], dots)
    return(rlang::exec(dist_fn, !!!args))
  }
}

#' Density function a named distribution
#'
#' @inheritParams reparam-dist
#'
#' @export
#' @concept distributions
ddist = function(dist, x, ...) {
  reparam_fn = try(rlang::as_function(sprintf(".reparam.%s", dist)), silent = TRUE)
  if (inherits(reparam_fn, "try-error")) {
    dist_fn = try(rlang::as_function(sprintf("d%s", dist)), silent = TRUE)
    if (inherits(dist_fn, "try-error")) {
      stop(
        "can't resolve function: ",
        sprintf("d%s", dist),
        " or reparameterise it."
      )
    }
    return(dist_fn(x, ...))
  } else {
    param = utils::head(rlang::list2(...), 2)
    dots = utils::tail(rlang::list2(...), -2)
    tmp = rlang::exec(reparam_fn, !!!param)
    dist_fn = try(rlang::as_function(sprintf("d%s", tmp$dist)), silent = TRUE)
    args = c(list(x = x), tmp[2:3], dots)
    return(rlang::exec(dist_fn, !!!args))
  }
}

#' Cumulative probability from a named distribution
#'
#' @inheritParams reparam-dist
#'
#' @export
#' @concept distributions
pdist = function(dist, q, ...) {
  reparam_fn = try(rlang::as_function(sprintf(".reparam.%s", dist)), silent = TRUE)
